type:
∀ {A : Sort u} {B : Sort v} {to : A → B} {of : B → A} {of_to : ∀ (a : A), of (to a) = a}
  {to_of : ∀ (b : B), to (of b) = b} {to_1 : A → B} {of_1 : B → A} {of_to_1 : ∀ (a : A), of_1 (to_1 a) = a}
  {to_of_1 : ∀ (b : B), to_1 (of_1 b) = b},
  { to := to, of := of, of_to := of_to, to_of := to_of } =
      { to := to_1, of := of_1, of_to := of_to_1, to_of := to_of_1 } →
    to = to_1 ∧ of = of_1
